const getAccountLedgerLines = `-- name: GetAccountLedgerLines :many
SELECT
    j.entry_number,
    j.entry_date,
    COALESCE(l.description, j.description, '') AS description,
    l.debit,
    l.credit
FROM t_journal_entry_lines l
JOIN t_journal_entries j ON j.id = l.journal_entry_id
WHERE l.account_id = $1::bigint
  AND j.status = 'POSTED'
  AND j.entry_date >= $2::date
  AND j.entry_date <= $3::date
ORDER BY j.entry_date ASC, j.id ASC, l.line_no ASC
`

type GetAccountLedgerLinesParams struct {
	AccountID int64
	FromDate  pgtype.Date
	ToDate    pgtype.Date
}

type GetAccountLedgerLinesRow struct {
	EntryNumber string
	EntryDate   pgtype.Date
	Description string
	Debit       pgtype.Numeric
	Credit      pgtype.Numeric
}

// Mutasi rinci satu akun pada rentang tanggal, terurut kronologis. Nomor jurnal
// dan tanggal ikut ditampilkan supaya pembaca bisa menelusuri asal angka.
func (q *Queries) GetAccountLedgerLines(ctx context.Context, arg GetAccountLedgerLinesParams) ([]GetAccountLedgerLinesRow, error) {
	rows, err := q.db.Query(ctx, getAccountLedgerLines, arg.AccountID, arg.FromDate, arg.ToDate)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GetAccountLedgerLinesRow
	for rows.Next() {
		var i GetAccountLedgerLinesRow
		if err := rows.Scan(
			&i.EntryNumber,
			&i.EntryDate,
			&i.Description,
			&i.Debit,
			&i.Credit,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

