const getPostedAccountBalances = `-- name: GetPostedAccountBalances :many

SELECT
    a.id AS account_id,
    a.code,
    a.name,
    a.account_type,
    a.normal_balance,
    COALESCE(SUM(l.debit), 0)::numeric AS total_debit,
    COALESCE(SUM(l.credit), 0)::numeric AS total_credit
FROM m_chart_of_accounts a
JOIN t_journal_entry_lines l ON l.account_id = a.id
JOIN t_journal_entries j ON j.id = l.journal_entry_id
WHERE a.deleted_at IS NULL
  AND j.status = 'POSTED'
  AND j.entry_date >= $1::date
  AND j.entry_date <= $2::date
GROUP BY a.id, a.code, a.name, a.account_type, a.normal_balance
ORDER BY a.code
`

type GetPostedAccountBalancesParams struct {
	FromDate pgtype.Date
	ToDate   pgtype.Date
}

type GetPostedAccountBalancesRow struct {
	AccountID     int64
	Code          string
	Name          string
	AccountType   string
	NormalBalance string
	TotalDebit    pgtype.Numeric
	TotalCredit   pgtype.Numeric
}

// =========================================================================
// MODUL AKUNTANSI (FASE 2C): LAPORAN KEUANGAN
// =========================================================================
//
// Laporan hanya membaca jurnal berstatus POSTED. Join terhadap
// t_journal_entry_lines bersifat INNER sehingga akun yang tidak pernah
// diposting (termasuk akun header) tidak pernah muncul sebagai baris laporan.
// Menjumlahkan debit/kredit per akun dari jurnal POSTED pada rentang tanggal
// inklusif. Bahan mentah Neraca, Laba Rugi, dan Neraca Saldo. Rentang tanggal
// panjang (dari awal tahun buku) menghasilkan saldo kumulatif untuk Neraca.
func (q *Queries) GetPostedAccountBalances(ctx context.Context, arg GetPostedAccountBalancesParams) ([]GetPostedAccountBalancesRow, error) {
	rows, err := q.db.Query(ctx, getPostedAccountBalances, arg.FromDate, arg.ToDate)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GetPostedAccountBalancesRow
	for rows.Next() {
		var i GetPostedAccountBalancesRow
		if err := rows.Scan(
			&i.AccountID,
			&i.Code,
			&i.Name,
			&i.AccountType,
			&i.NormalBalance,
			&i.TotalDebit,
			&i.TotalCredit,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

