const softDeletePurchaseOrder = `-- name: SoftDeletePurchaseOrder :execrows
UPDATE t_purchase_orders
SET
    deleted_at = NOW(),
    updated_at = NOW(),
    updated_by = $1::bigint
WHERE id = $2::bigint
  AND deleted_at IS NULL
  AND status = 'PENDING'
`

type SoftDeletePurchaseOrderParams struct {
	UpdatedBy pgtype.Int8
	ID        int64
}

// Pencabutan dokumen PO memakai soft delete: baris TIDAK dihapus fisik, hanya
// diisi deleted_at. Seluruh query pembacaan PO sudah memfilter deleted_at IS NULL,
// jadi dokumen ini langsung hilang dari daftar tanpa merusak riwayat keuangan.
// Baris detail sengaja dibiarkan agar jejak audit barang tetap utuh.
//
// Syarat status=PENDING adalah pagar terakhir setelah header dikunci. Dokumen
// yang sudah APPROVED/RECEIVED tidak boleh hilang dari daftar aktif.
func (q *Queries) SoftDeletePurchaseOrder(ctx context.Context, arg SoftDeletePurchaseOrderParams) (int64, error) {
	result, err := q.db.Exec(ctx, softDeletePurchaseOrder, arg.UpdatedBy, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const transitionPurchaseOrderStatus = `-- name: TransitionPurchaseOrderStatus :execrows
UPDATE t_purchase_orders
SET
    status = $1::text,
    updated_at = NOW(),
    updated_by = $2::bigint,
    approved_by = CASE WHEN $1::text = 'APPROVED' THEN $2::bigint ELSE approved_by END,
    approved_at = CASE WHEN $1::text = 'APPROVED' THEN NOW() ELSE approved_at END,
    rejected_by = CASE WHEN $1::text = 'REJECTED' THEN $2::bigint ELSE rejected_by END,
    rejected_at = CASE WHEN $1::text = 'REJECTED' THEN NOW() ELSE rejected_at END,
    reject_reason = CASE WHEN $1::text = 'REJECTED' THEN $3::text ELSE reject_reason END
WHERE id = $4::bigint
  AND deleted_at IS NULL
  AND status = ANY($5::text[])
  AND NOT (status = ANY($6::text[]))
`

type TransitionPurchaseOrderStatusParams struct {
	NewStatus    string
	UpdatedBy    pgtype.Int8
	RejectReason pgtype.Text
	ID           int64
	AllowFrom    []string
	ForbidFrom   []string
}

// Perpindahan status memakai compare-and-swap: baris hanya berubah kalau status
// saat ini masih termasuk daftar asal yang diizinkan, dan bukan salah satu
// status yang sedang dikunci untuk Transitions lain.
//
// Versi lama membaca status lewat SELECT lalu menulis tanpa syarat status, jadi
// approve dan cancel yang datang bersamaan bisa sama-sama berhasil dan dokumen
// diam-diam berakhir pada status penulisan terakhir. nowrows() di lapisan
// pemanggil menerjemahkan 0 baris terpengaruh menjadi ErrKonflikStatus, bukan
// diam-diam dianggap berhasil.
//
// allow_from dipakai saat transisi hanya boleh dari satu status (mis. approve
// hanya dari PENDING). forbid_from dipakai untuk mengunci status yang sedang
// Competing: hanya dikirim saat transisi punya status asal tunggal.
func (q *Queries) TransitionPurchaseOrderStatus(ctx context.Context, arg TransitionPurchaseOrderStatusParams) (int64, error) {
	result, err := q.db.Exec(ctx, transitionPurchaseOrderStatus,
		arg.NewStatus,
		arg.UpdatedBy,
		arg.RejectReason,
		arg.ID,
		arg.AllowFrom,
		arg.ForbidFrom,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

